<?php require_once __DIR__.'/../config/auth.php';require_role('kasir');$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$s=db()->prepare("SELECT t.*,p.method FROM transactions t JOIN payments p ON p.transaction_id=t.id WHERE t.cashier_id=? AND DATE(t.created_at) BETWEEN ? AND ? ORDER BY t.id DESC");$s->execute([user()['id'],$from,$to]);$rows=$s->fetchAll();$pageTitle='Riwayat Transaksi';$active='riwayat';include __DIR__.'/../includes/header.php';?>
<section class="card"><form class="filter-row"><label>Dari<input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn primary">Tampilkan</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Tanggal</th><th>Metode</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['invoice'])?></strong></td><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td><td><?=ucfirst($r['method'])?></td><td><?=rupiah($r['total'])?></td><td><a class="btn soft sm" href="transaksi_detail.php?id=<?=urlencode($r['invoice'])?>">Detail</a></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state">Tidak ada transaksi pada periode ini.</div><?php endif;?></div></section><?php include __DIR__.'/../includes/footer.php';?>

